use std::collections::HashSet;

fn remove_elements(a: &[i32], b: &[i32]) -> Vec<i32> {
    // Create a HashSet from the second slice for quick lookups
    let b_set: HashSet<i32> = b.iter().cloned().collect();
    
    // Create a HashSet to store unique results
    let mut result_set: HashSet<i32> = HashSet::new();
    
    // Iterate over the first slice and collect elements not in the second slice
    for &value in a {
        if !b_set.contains(&value) {
            result_set.insert(value);
        }
    }
    
    // Convert the HashSet back to a Vec
    result_set.into_iter().collect()
}

